-- Fourth batch of explicitly labelled supplemental study outlines for MBH histology.
-- Idempotent: existing answers are never overwritten.
with supplemental_answers(id, answer) as (
  values
  ('eab2ad36-586c-549b-893f-e66e32671eb6', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Физиологическая регенерация — постоянное обновление клеток и компонентов ткани в норме; репаративная — восстановление после повреждения. Реституция восстанавливает исходную ткань, субституция замещает дефект соединительной тканью. Эпителии, кровь и рыхлая соединительная ткань обычно обновляются активно; скелетная мышца имеет ограниченный потенциал за счёт сателлитных клеток, а миокард и нейроны ЦНС — низкий. Способность зависит от сохранности стволовых клеток, сосудов, матрикса и микроокружения.'),
  ('4834c8c7-104e-50f3-ac35-cd5199a13efc', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Ткани — уровень организации между клетками и органами. Основные эмбриональные источники: эктодерма формирует эпидермис и нервную систему; энтодерма — эпителий пищеварительной и большей части дыхательной систем; мезодерма — соединительные ткани, мышцы, кровь, эндотелий и мезотелий. Дифференцировка регулируется экспрессией генов, эпигенетическими механизмами, сигнальными молекулами и взаимодействием с внеклеточным матриксом. Источники отдельных тканей могут иметь исключения, поэтому их нужно соотносить с конкретным органом.'),
  ('2dfb0d0d-82d8-5672-ab41-f18c6fd9c319', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Репаративная регенерация — восстановление ткани после повреждения. Возможны полное восстановление исходной структуры (реституция) и замещение дефекта соединительной тканью (субституция); результат зависит от типа ткани, объёма повреждения, сохранности стромы и кровоснабжения. Эпителии и кроветворная ткань обладают высокой регенераторной активностью; нейроны ЦНС и кардиомиоциты восстанавливаются ограниченно. Восстановление включает воспалительную фазу, пролиферацию клеток, синтез матрикса и ремоделирование.'),
  ('8721ce63-68ed-5497-a3a8-d172127976a5', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Секреторный цикл включает захват исходных веществ, синтез секрета, внутриклеточную обработку и накопление, выделение и восстановление. Белки синтезируются на гранулярной ЭПС, модифицируются в комплексе Гольджи и упаковываются в гранулы; липиды синтезируются преимущественно в гладкой ЭПС. Мерокриновая секреция происходит экзоцитозом, апокриновая — с отделением апикальной части цитоплазмы, голокриновая — при разрушении всей клетки.'),
  ('c85636ed-edc9-541e-bfe9-af5de01ff2a1', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Макрофаги — фагоцитирующие клетки моноцитарно-макрофагальной системы; моноциты крови мигрируют в ткани и дифференцируются, а в некоторых органах существуют долгоживущие тканевые популяции. Макрофаги имеют неправильную форму, развитые лизосомы и фагосомы; удаляют микробы и клеточный детрит, выделяют цитокины и представляют антигены T-лимфоцитам. Макрофагическая система включает моноциты и тканевые макрофаги печени, лёгких, ЦНС и других органов.'),
  ('94520787-614a-54cc-88ef-d9908fcf1f47', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Тканевые базофилы (тучные клетки) развиваются из кроветворных предшественников и созревают в тканях; содержат гранулы с гистамином, протеазами и другими медиаторами, участвуют в аллергических реакциях и воспалении. Плазмоциты происходят из активированных B-лимфоцитов, синтезируют иммуноглобулины; имеют эксцентричное ядро с «колесовидным» хроматином, базофильную цитоплазму и светлую перинуклеарную зону комплекса Гольджи.'),
  ('2c400fe9-93da-5741-81ca-37d0ca592f72', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Ретикулярная ткань образует каркас кроветворных и многих лимфоидных органов; её клетки и ретикулярные волокна создают сеть для клеток крови и иммунной системы. Белая жировая ткань состоит из крупных унилокулярных адипоцитов с ядром по периферии и запасает энергию, выделяет адипокины и участвует в терморегуляции. Бурая жировая ткань содержит многокапельные адипоциты, много митохондрий и обеспечивает теплопродукцию. Пигментная ткань содержит клетки с меланином и характерна для отдельных участков организма.'),
  ('f0b0b649-6c46-5993-b6b4-9bd466bb7216', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Хрящевая ткань состоит из хондроцитов в лакунах и богатого матрикса с коллагеном II типа и протеогликанами; сосудов нет, питание идёт диффузией из надхрящницы или синовиальной жидкости. Гиалиновый хрящ расположен в суставных поверхностях, трахее и рёберных хрящах; эластический содержит эластические волокна (ушная раковина, надгортанник); волокнистый богат коллагеном I (межпозвоночные диски, симфиз). Рост бывает интерстициальным и аппозиционным; регенерация ограничена, с возрастом матрикс меняется.'),
  ('4f654e07-d3d2-5386-b6ad-3177f49299f4', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Фибробласты — активные клетки соединительной ткани с развитой гранулярной ЭПС и комплексом Гольджи; синтезируют коллаген, эластин, фибронектин и компоненты основного вещества. Фиброциты — более зрелые, менее активные клетки с вытянутой формой и меньшим количеством органелл; поддерживают матрикс. В заживлении фибробласты могут приобретать свойства миофибробластов. К другим коллагенообразующим клеткам относят специализированные фибробласты сухожилий и хондробласты/остеобласты, синтезирующие матрикс хряща и кости.'),
  ('30eae9a3-4afd-5f48-a106-fc691cf585de', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Сердечная мышечная ткань развивается преимущественно из висцеральной мезодермы. Кардиомиоциты короткие, ветвящиеся, имеют одно или два центральных ядра и поперечную исчерченность; клетки соединены вставочными дисками с десмосомами, фасциями адгезии и щелевыми контактами. Богатая сеть капилляров и многочисленные митохондрии поддерживают непрерывную работу. Регенерация зрелых кардиомиоцитов ограничена; после значимого повреждения участок часто замещается рубцовой тканью.'),
  ('2db3cd0d-c797-5f28-80ef-10d8c690e2ca', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Специализированные структуры эпителиоцитов включают микроворсинки (увеличивают площадь всасывания), подвижные реснички (перемещают жидкость и частицы), стереоцилии (длинные неподвижные выросты для всасывания/механорецепции), а также плотные контакты, десмосомы и полудесмосомы. Базальная мембрана состоит из базальной пластинки с ламининами и коллагеном IV и связанной ретикулярной пластинки. Она фиксирует эпителий, разделяет тканевые компартменты, регулирует фильтрацию и миграцию клеток и служит матрицей при регенерации.'),
  ('3fec3a56-d303-57ba-af6a-a2dbcd5c51fc', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Межклеточное вещество рыхлой соединительной ткани состоит из волокон и основного вещества. Коллагеновые волокна придают прочность, эластические обеспечивают растяжение и возврат формы, ретикулярные образуют опорные сети. Основное вещество богато водой и гидратированными макромолекулами, поэтому обеспечивает диффузию метаболитов. Фибробласты синтезируют компоненты матрикса и регулируют его обновление; при повреждении они участвуют в формировании грануляционной ткани и рубца.'),
  ('de73550e-0354-5acf-a7c3-c9c36d40202e', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Ретикулярная соединительная ткань формирует строму красного костного мозга, лимфатических узлов и селезёнки; сеть ретикулярных волокон поддерживает свободные клетки. Белая жировая ткань образована унилокулярными адипоцитами с одной крупной липидной каплей, ядро смещено к периферии; функции — энергетический резерв, эндокринная регуляция и амортизация. Бурая жировая ткань богата митохондриями с UCP1 и производит тепло. Топография и соотношение типов зависят от возраста и участка тела.'),
  ('fbbe1137-c0f7-5b79-89f0-8264fd872460', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Гиалиновый хрящ имеет стекловидный матрикс, хондроциты в лакунах часто располагаются изогенными группами; обычно покрыт надхрящницей, кроме суставного хряща. Он формирует суставные поверхности, кольца трахеи и рёберные хрящи. Питание осуществляется диффузией, поскольку сосудов нет. Интерстициальный рост происходит делением хондроцитов внутри матрикса, аппозиционный — за счёт хондробластов надхрящницы. Регенерация медленная и неполная из-за слабой васкуляризации.'),
  ('7effde8c-e18a-54c7-8655-b8803490dc51', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эластический хрящ содержит хондроциты в лакунах и густую сеть эластических волокон; встречается в ушной раковине и надгортаннике, сохраняет форму при изгибе и обычно имеет надхрящницу. Волокнистый хрящ содержит толстые пучки коллагена I типа и ряды хондроцитов между ними; расположен в межпозвоночных дисках, лобковом симфизе и местах прикрепления сухожилий. Он устойчив к растяжению и сжатию, надхрящница обычно отсутствует. Питание обоих типов осуществляется диффузией, регенерация ограничена.'),
  ('e056f067-2f64-5ec3-b03a-2772b38a90e6', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Структурная единица скелетной мышцы — мышечное волокно, окружённое сарколеммой и базальной мембраной; внутри расположены миофибриллы из саркомеров. Потенциал действия распространяется по сарколемме и T-трубочкам, вызывает высвобождение Ca2+ из саркоплазматического ретикулума. Ca2+ связывается с тропонином C, открывая участки актина для миозина; циклическое образование и разрыв поперечных мостиков с затратой АТФ приводит к скольжению филаментов и сокращению.'),
  ('11844d84-3155-5dee-849e-4b795630e511', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Скелетная мышца состоит из длинных многоядерных волокон с периферическими ядрами и выраженной исчерченностью; сердце — из ветвящихся кардиомиоцитов с центральными ядрами и вставочными дисками. Скелетная мышца сокращается произвольно и регенерирует ограниченно благодаря сателлитным клеткам; сердечная работает непроизвольно, сокращения координируются электрическими контактами, а восстановление крайне ограничено. Оба типа содержат саркомеры и актин-миозиновый аппарат.'),
  ('c05482ec-ef40-5a52-a635-3b8a03bef4df', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Рыхлая волокнистая соединительная ткань содержит разнообразные клетки, много основного вещества и волокна. Коллагеновые волокна обеспечивают прочность, эластические — растяжимость, ретикулярные формируют тонкую опорную сеть. Аморфное вещество включает воду, гликозаминогликаны, протеогликаны и адгезивные гликопротеины; оно обеспечивает диффузию и связывает клетки с матриксом. Фибробласты синтезируют коллаген, эластин и компоненты основного вещества, участвуют в заживлении и ремоделировании.'),
  ('1c88d19c-49fe-5b70-82f7-ac61cce3408f', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Стволовые клетки способны к самообновлению и дифференцировке в несколько специализированных типов; их судьба зависит от ниши и сигналов. В желудочно-кишечном тракте стволовые клетки расположены в области желез/крипт и обеспечивают постоянное обновление эпителия. Кроветворные стволовые клетки костного мозга дают начало всем линиям клеток крови и поддерживают гемопоэз на протяжении жизни. Клиническое значение включает трансплантацию кроветворных клеток и регенеративные подходы, однако потенциал и безопасность зависят от типа клеток и метода.'),
  ('0e15f25a-4d34-5830-80b3-3af3ebaf1ed6', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Ткань — система клеток и межклеточного вещества, объединённых происхождением, строением и функциями. Выделяют четыре основные группы: эпителиальную, соединительную (включая кровь и скелетные разновидности), мышечную и нервную. Эпителий образует покровы и железы; соединительная ткань обеспечивает опору, трофику и защиту; мышечная — сокращение; нервная — приём и передачу информации. Для характеристики ткани описывают клеточный состав, матрикс, происхождение, локализацию, функции и способность к регенерации.')
)
update public.exam_questions q
set answer = s.answer, updated_at = now()
from supplemental_answers s
where q.id = s.id::uuid
  and q.subject_slug = 'histology'
  and nullif(btrim(q.answer), '') is null;
